// GitHub API'den Bultenler/ klasorunu listeler, henuz mail atilmamis
// bultenleri bulur.
//
// v1'den fark: latest.json'a BAGIMLI DEGIL. Rutin isaretci dosyasini yazmayi
// unutsa bile yeni bulten dosyasi klasorde goruldugu an mail gider. (v1'de
// rutin latest.json'i yazmayi biraktigi icin 10 Agustos'ta iki bulten
// postalanmamisti.)
//
// Ayrica raw.githubusercontent yerine GitHub Contents API kullaniliyor:
// raw CDN yanitlari ~5 dk onbelleklenir ve ?cb= cache-buster'i bunu
// ATLATMIYOR (olculdu) - yani push'tan hemen sonraki tarama eski icerigi
// gorebiliyor. API onbelleklenmiyor.
//
// 21 Agustos 2026 duzeltmesi - EN YENI ONCE:
// Onceki surum bekleyenleri KRONOLOJIK sirada (en eski once) postaliyordu.
// v2 import edilince static data bos oldugu icin 10 Agustos'tan bu yana
// 25 bulten birikmis backlog oldu ve tur basina 3 mail limitiyle sirayla
// en eskiler gitti: ilk tur 10 Agustos'u, ikinci tur 11 Agustos'u postaladi.
// Gunun bulteni sirada 25. oldugu icin ~9 tur (9 saat) sonra gelecekti.
// Artik: (1) siralama EN YENIDEN eskiye, (2) TAZE_SAAT'ten eski bekleyenler
// hic postalanmaz, sessizce "gonderildi" isaretlenir - arsiv maili yagmaz.
// En yeni bekleyen bulten yas ne olursa olsun her zaman postalanir (rutin
// gunlerce durmus olsa bile son bulten gelir).

// --- ilk calisma tohumlamasi ------------------------------------------
// Workflow yeni import edildiginde static data bostur. Arsivdeki tum
// bultenleri birden postalamamak icin: bu esikten ESKI her dosya
// "gonderilmis" sayilir, esikten YENI olanlar ilk calismada mail olur.
const ESIK = '2026-08-21-0000.md';

// Esikten yeni oldugu halde gonderilmesini istemedigin dosyalar.
// Ornek: eski (v1) workflow o bulteni zaten postaladiysa buraya ekle.
const ZATEN_GONDERILDI = [];

// Tek calismada en fazla kac mail atilsin? Kalanlar sonraki saate kalir.
const TUR_BASINA_LIMIT = 3;

// Bekleyen bir bulten bu yastan (saat) eskiyse postalanmaz; sessizce
// gonderildi isaretlenir. Backlog birikirse eski haber maili gelmesin diye.
// En yeni bekleyen bulten bu kuralin DISINDA - o her zaman gider.
const TAZE_SAAT = 36;
// ----------------------------------------------------------------------

const store = $getWorkflowStaticData('global');
const res = $input.first().json || {};

const kod = res.statusCode;
const govde = typeof res.body === 'string' ? res.body : JSON.stringify(res.body ?? '');
const ornek = govde.slice(0, 200);

if (kod !== undefined && kod !== 200) {
  return [{ json: { gonderilecek: false, neden: 'GitHub API listesi cekilemedi (HTTP ' + kod + ')', ornek } }];
}

let liste;
try {
  liste = (res.body && typeof res.body === 'object') ? res.body : JSON.parse(govde);
} catch (e) {
  return [{ json: { gonderilecek: false, neden: 'Liste JSON olarak ayristirilamadi: ' + e.message, ornek } }];
}

if (!Array.isArray(liste)) {
  return [{ json: { gonderilecek: false, neden: 'GitHub API dizi dondurmedi (rate limit olabilir)', ornek } }];
}

// Sadece bulten dosyalari: YYYY-AA-GG-SSDD.md (README.md ve latest.json haric)
const BULTEN = /^\d{4}-\d{2}-\d{2}-\d{4}\.md$/;
const dosyalar = liste
  .filter((f) => f && f.type === 'file' && BULTEN.test(f.name))
  .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));

if (!dosyalar.length) {
  return [{ json: { gonderilecek: false, neden: 'Klasorde bulten dosyasi bulunamadi' } }];
}

// Tohumlama (ilk calisma) + v1'den gecis
if (!Array.isArray(store.gonderilenler)) {
  const tohum = dosyalar.filter((f) => f.name < ESIK).map((f) => f.name);
  for (const d of ZATEN_GONDERILDI) if (!tohum.includes(d)) tohum.push(d);
  // v1 static data'si duruyorsa onu da hesaba kat
  if (store.sonGonderilen && !tohum.includes(store.sonGonderilen)) tohum.push(store.sonGonderilen);
  store.gonderilenler = tohum;
  store.tohumlandi = new Date().toISOString();
}

const gonderilmis = new Set(store.gonderilenler);

// EN YENIDEN eskiye. Backlog varsa gunun bulteni ilk turda gider.
const bekleyen = dosyalar
  .filter((f) => !gonderilmis.has(f.name))
  .sort((a, b) => (a.name < b.name ? 1 : a.name > b.name ? -1 : 0));

if (!bekleyen.length) {
  return [{ json: { gonderilecek: false, neden: 'yeni bulten yok', arsivdeki: dosyalar.length } }];
}

// Dosya adindaki zaman damgasi Europe/Istanbul (UTC+3, DST yok) -> epoch ms
function zamanMs(ad) {
  const m = /^(\d{4})-(\d{2})-(\d{2})-(\d{2})(\d{2})\.md$/.exec(ad);
  if (!m) return null;
  return Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4] - 3, +m[5]);
}

const simdi = Date.now();
const postalanacak = [];
const eskiAtlanan = [];

bekleyen.forEach((f, i) => {
  const t = zamanMs(f.name);
  // Zamani okunamayan dosyayi sessizce dusurmeyiz: taze say, mail gitsin.
  const yasSaat = t === null ? 0 : (simdi - t) / 3600000;
  if (i === 0 || yasSaat <= TAZE_SAAT) postalanacak.push(f);
  else eskiAtlanan.push(f.name);
});

// Atlanan eski bultenler bir daha sirada beklemesin diye hemen isaretlenir.
// (Mail atilmadi - kasten. Arsiv GitHub'da duruyor.)
if (eskiAtlanan.length) {
  for (const ad of eskiAtlanan) {
    if (!store.gonderilenler.includes(ad)) store.gonderilenler.push(ad);
  }
  store.gonderilenler = store.gonderilenler.slice(-200);
  store.sonAtlanan = { zaman: new Date().toISOString(), adet: eskiAtlanan.length };
}

if (!postalanacak.length) {
  return [{ json: {
    gonderilecek: false,
    neden: 'bekleyen bultenlerin hepsi ' + TAZE_SAAT + ' saatten eski - atlandi',
    atlanan: eskiAtlanan.length,
  } }];
}

const secilen = postalanacak.slice(0, TUR_BASINA_LIMIT);

// Her bulten icin bir item. Sonraki dugumler item basina calisir.
return secilen.map((f) => ({
  json: {
    gonderilecek: true,
    dosya: f.name,
    // Contents API URL'i - raw CDN onbellegine takilmaz
    url: f.url,
    bekleyen: postalanacak.length,
    buTurda: secilen.length,
    atlanan: eskiAtlanan.length,
  },
}));

// Bultenin Markdown'ini e-postaya uygun HTML'e cevirip Gmail API'nin
// messages/send bekledigi base64url RFC822 mesajini uretir.
// Bu dugum HER ITEM icin bir kez calisir (runOnceForEachItem).
//
// v1'den fark: mail konusu latest.json'daki "baslik" alanindan degil,
// bultenin kendi H1 satirindan okunur - yani islemek icin isaretci
// dosyasina hic ihtiyac yok.

const dosya = $('Gonderilmeyenleri bul').item.json.dosya;
const md = String($json.markdown || '');

const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Satir ici bicimleme: kod, kalin, sonra ciplak URL'leri link yap.
function inline(s) {
  let t = esc(s);
  t = t.replace(/`([^`]+)`/g, '<code style="background:#f2f2f4;padding:1px 4px;border-radius:3px">$1</code>');
  t = t.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  t = t.replace(/(https?:\/\/[^\s<]+)/g,
    '<a href="$1" style="color:#2d6cdf;word-break:break-all">$1</a>');
  return t;
}

const lines = md.split(/\r?\n/);

// Mail konusu = bultenin H1'i
let baslik = '';
for (const l of lines) {
  const t = l.trim();
  if (t.startsWith('# ')) { baslik = t.slice(2).trim(); break; }
}
if (!baslik) baslik = 'AI Haber Bulteni - ' + dosya;

const out = [];
let inList = false;
const closeList = () => { if (inList) { out.push('</ul>'); inList = false; } };

for (const rawLine of lines) {
  const line = rawLine.trim();

  if (!line) { closeList(); continue; }
  if (/^---+$/.test(line)) {
    closeList();
    out.push('<hr style="border:0;border-top:1px solid #e2e2e6;margin:22px 0">');
    continue;
  }
  if (line.startsWith('# ')) {      // H1 = mail konusu, govdede tekrar etmiyoruz
    closeList();
    continue;
  }
  if (line.startsWith('## ')) {
    closeList();
    out.push('<h2 style="font-size:17px;margin:26px 0 10px">' + inline(line.slice(3)) + '</h2>');
    continue;
  }
  // Eski (Gmail'den arsivlenmis) bultenlerde bolum basliklari '##' yerine
  // ciplak emoji satiri: '🟣 CLAUDE & ANTHROPIC'. Onlari da baslik say.
  if (/^(\u{1F7E3}|\u{1F9E0}|\u{1F4BB})/u.test(line) && line.length < 80) {
    closeList();
    out.push('<h2 style="font-size:17px;margin:26px 0 10px">' + inline(line) + '</h2>');
    continue;
  }
  if (/^[-*•]\s+/.test(line)) {
    if (!inList) { out.push('<ul style="padding-left:20px;margin:10px 0">'); inList = true; }
    out.push('<li style="margin:0 0 12px;line-height:1.55">' + inline(line.replace(/^[-*•]\s+/, '')) + '</li>');
    continue;
  }
  if (inList) {   // madde altindaki devam satiri
    const last = out.pop();
    out.push(last.replace(/<\/li>$/, '<br>' + inline(line) + '</li>'));
    continue;
  }
  out.push('<p style="margin:8px 0;line-height:1.55">' + inline(line) + '</p>');
}
closeList();

const html =
  '<!doctype html><html><body style="margin:0;padding:20px;background:#ffffff;' +
  'font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;' +
  'font-size:15px;color:#1a1a1c">' +
  '<div style="max-width:680px;margin:0 auto">' + out.join('\n') +
  '<hr style="border:0;border-top:1px solid #e2e2e6;margin:26px 0">' +
  '<p style="font-size:12px;color:#76767c;margin:0">' +
  'Kaynak: <a href="https://github.com/ahmetem/GunlukRutin/blob/main/AI%20Haberleri/Bultenler/' +
  encodeURIComponent(dosya) + '" style="color:#76767c">' + esc(dosya) + '</a>' +
  ' &middot; AI Haber Bulteni rutini</p>' +
  '</div></body></html>';

// RFC 2047 - Turkce karakter ve emoji iceren konu basligi
const subject = '=?UTF-8?B?' + Buffer.from(baslik, 'utf8').toString('base64') + '?=';

const mime = [
  'To: posta@ahmetkaraca.com',
  'Subject: ' + subject,
  'MIME-Version: 1.0',
  'Content-Type: text/html; charset="UTF-8"',
  'Content-Transfer-Encoding: base64',
  '',
  Buffer.from(html, 'utf8').toString('base64'),
].join('\r\n');

const raw = Buffer.from(mime, 'utf8').toString('base64')
  .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

return { json: { raw, dosya, konu: baslik } };

// Yalnizca GERCEKTEN gonderilen dosyalari "gonderildi" olarak isaretle.
//
// "Mail gonder" dugumu onError=continueRegularOutput ile calisir: bir mail
// patlasa da execution devam eder. Basarisiz olan dosya isaretlenmez, bir
// sonraki saatte tekrar denenir. Basarili olanlar tekrar gonderilmez.

const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.gonderilenler)) store.gonderilenler = [];

const hazirlik = $('Mail govdesini hazirla').all();
const gelen = $input.all();

const basarili = [];
const basarisiz = [];

for (let i = 0; i < gelen.length; i++) {
  const j = gelen[i].json || {};
  const dosya = hazirlik[i] && hazirlik[i].json ? hazirlik[i].json.dosya : undefined;
  if (!dosya) continue;

  // Gmail messages/send basarili yanitinda id/threadId doner
  const basarilimi = !j.error && (j.id || j.threadId);

  if (basarilimi) {
    if (!store.gonderilenler.includes(dosya)) store.gonderilenler.push(dosya);
    basarili.push(dosya);
  } else {
    const hata = j.error
      ? (j.error.message || JSON.stringify(j.error).slice(0, 200))
      : 'Gmail yaniti id icermiyor';
    basarisiz.push({ dosya, hata });
  }
}

// Listeyi sinirla - sadece son 200 dosya adi yeterli
store.gonderilenler = store.gonderilenler.slice(-200);
store.sonGonderimZamani = new Date().toISOString();

return [{
  json: {
    gonderildi: basarili,
    basarisiz,
    zaman: store.sonGonderimZamani,
    hafizadaki: store.gonderilenler.length,
  },
}];
